mapper.insert:
INSERT INTO ${tableName}
    (

    geom


    ,layertype


    ,calarea


    ,bsm


    ,ysdm


    ,gzqlxdm


    ,gzqmj


    ,sm


    )
values

(

        ST_GeomFromText(#{item.the_geom},4326)


        ,#{layerType}


        ,#{item.calarea}


        ,#{item.bsm}


        ,#{item.ysdm}


        ,#{item.gzqlxdm}


        ,CAST(#{item.gzqmj} AS double precision)


        ,#{item.sm}

)

create table IF NOT EXISTS ${tableName} (like jsydgzq_ceshitable INCLUDING indexes including constraints including comments including defaults) ;
CREATE SEQUENCE IF NOT EXISTS ${tableName}_gid_seq
    INCREMENT 1
    START 1
    MINVALUE 1
    MAXVALUE 2147483647
    CACHE 1;
alter table ${tableName} alter column "gid" set default nextval('${tableName}_gid_seq');

CREATE VIEW view_${tableName} AS
SELECT gid, geom, bsm, minx, miny, maxx, maxy, GZQLXDM, GZQMJ
FROM ${tableName}

mapper.select:
SELECT row_to_json(fc) FROM ( SELECT 'FeatureCollection' AS type, '212' AS id, array_to_json(array_agg(f)) AS features FROM ( SELECT 'Feature' AS type
,ST_AsGeoJSON(geom)::json as geometry
,( SELECT row_to_json(t) FROM ( SELECT bsm as tbbh,bsm,'' as dlmc,'' as zldwmc
,ysdm,gzqlxdm,gzqmj,sm
) AS t ) AS properties FROM ${tableName}
and bsm in
#{item}
) AS f ) AS fc

select
count(1)
from ${tableName}


        and bsm in

            #{item}
